   101	   * reconciliation-clean (reconcile().ok === true) — the settlement is proven,
   102	   * not merely attempted. A fulfilled-but-not-yet-final fetch is `'claimed'`,
   103	   * so callers never bet real settlement on an assumption.
   104	   */
   105	  finality?: 'claimed' | 'final';
   106	}
