   124	  completedAt: string;
   125	  recordedAt: string;
   126	}
   127	
   128	/**
   129	 * A payment rail: one interface, pluggable backends.
   130	 * Backends: x402 facilitator, Cloudflare Pay Per Crawl, self-hosted 402.
   131	 * The interface is stable; backend field names are not (draft-caveat discipline).
   132	 */
   133	export interface PaymentRequest {
   134	  url: UrlString;
   135	  method: string;
   136	  headers: HeaderRecord;
   137	  contentType?: string;
   138	}
