   155	export interface PaymentRail {
   156	  readonly id: string;
   157	  quote(req: PaymentRequest): Promise<Quote>;
   158	  authorize(req: PaymentRequest, quote: Quote): Promise<RailAuthorization>;
   159	  settle(req: PaymentRequest, authorization: RailAuthorization): Promise<RailSettlement>;
   160	}"}

