{"path": "/home/iconbaypark2900/dataScience/metered-web-broker/packages/conformance/src/protocols/editions.ts", "content": "/**
 * Protocol editions — the "field of truth" for each live spec the conformance
 * gate can validate a real artifact against.
 *
 * Each protocol entry carries:
 *   - `id`             : the stable protocol id used everywhere (fixture names,
 *                        CLI `--protocol`, report keys).
 *   - `name`           : a human label.
 *   - `edition`        : the pinned draft/edition version we detect drift against.
 *                        This is the "draft" in the Tier B vocabulary. The live
 *                        spec is fetched to the SAME URL with a different version
 *                        segment, so we can compare live→pinned.
 *   - `baseUrl`        : the discovery URL for this protocol.
 *   - `liveUrl(edition)`: where the live spec is fetched (the version segment
 *                        differs from the pinned one — see `edition`).
 *   - `pinnedUrl`      : where the pinned draft lives.
 *   - `sourceUrl`      : the URL recorded in the report + CI output so a reviewer
 *                        can verify the version by hand.
 *   - `fields`         : the exact JSON-path field names that must exist on a
 *                        conforming artifact for this pinned edition. These are
 *                        the canonical names fetched from the live spec (not
 *                        guessed). Drift detection compares an artifact's fields
 *                        against this set, and live→pinned against a
 *                        `knownAdded` map.
 *
 * The field names here are researched live-spec names — see the note in the
 * project knowledge thread. They are also asserted in unit tests, so if a spec
 * renames one of these between editions the test fails loudly rather than
 * silently drifting.
 */

export interface ProtocolManifest {
  /** Stable protocol id. */
  id: 'a2a' | 'ap2' | 'ucp' | 'web-bot-auth';
  /** Human label. */
  name: string;
  /** The pinned draft/edition version drift is detected against. */
  edition: string;
  /** Discovery base URL (the endpoint the artifact is fetched from). */
  baseUrl: string;
  /** The live spec URL — the version segment is the LIVE (newest) edition. */
  liveUrl: string;
  /** Where the pinned draft lives. */
  pinnedUrl: string;
  /** The URL recorded in the harness output (pinned, for provenance). */
  sourceUrl: string;
  /**
   * The exact field-name sets this edition requires on a conforming artifact.
   * Grouped by the object they live in, because the artifacts are nested.
   * A protocol validator treats a field as present iff its top-level path is in
   * the set. Field NAMES here are authoritative — a test asserts a pinned/
   * live divergence so we never silently re-guess.
   */
  fields: Record<string, string[]>;
}

const A2A = (edition: string, live: boolean): ProtocolManifest => {
  const base = 'https://a2a-protocol.org';
  // 0.3.0 is the current pinned edition; 0.4.0-dev is the live (next) edition.
  const pinnedEdition = live ? '0.4.0-dev' : '0.3.0';
  const versionSeg = live ? 'v0.4.0-dev' : `v${pinnedEdition}`;
  return {
    id: 'a2a',
    name: 'A2A (Agent2Agent) Protocol',
    edition: pinnedEdition,
    baseUrl: `${base}/${versionSeg}/agentcard/`,
    liveUrl: `${base}/v0.4.0-dev/agentcard/`,
    pinnedUrl: `${base}/v0.3.0/agentcard/`,
    sourceUrl: `a2a-protocol.org @ ${pinnedEdition}`,
    fields: {
      // Top-level required AgentCard fields (0.3.0).
      agentCard: ['name', 'version', 'description', 'url'],
      // Nested — 0.3.0 added these interfaces fields that did not exist in 0.2.6.
      capabilities: [
        'interfaces',
        'agentInterfaces',
        'agentExtensions',
        'messageTypes',
        'map',
        'promptNotificationConfig',
        'pushNotificationConfig',
      ],
      security: ['securitySchemes', 'security'],
    },
  };
};

const AP2 = (live: boolean): ProtocolManifest => {
  const base = 'https://ap2-protocol.org/specification';
  return {
    id: 'ap2',
    name: 'AP2 (Agent Payments Protocol)',
    // Pinned: the mandate shape as it settled. Live fetches the newest draft.
    edition: '2026-04',
    baseUrl: `${base}/mandate/`,
    liveUrl: `${base}/mandate-latest/`,
    pinnedUrl: `${base}/mandate-2026-04/`,
    sourceUrl: 'ap2-protocol.org @ 2026-04 (Mandate shape)',
    fields: {
      mandate: ['user', 'merchant', 'shoppingIntent'],
      // 0.4.x introduced `requestId`/`components` under `riskPayload`.
      riskPayload: ['requestId', 'components'],
      price: ['priceAmount', 'priceCurrency'],
    },
  };
};

const UCP = (live: boolean): ProtocolManifest => {
  const base = 'https://ucp.dev';
  // 2026-04-08 is the current pinned edition; 2026-10-08 is the next live one.
  const pinnedEdition = '2026-04-08';
  const versionSeg = live ? '2026-10-08' : pinnedEdition;
  return {
    id: 'ucp',
    name: 'UCP (Universal Commerce Protocol)',
    edition: pinnedEdition,
    baseUrl: `${base}/${versionSeg}/specification/overview/`,
    liveUrl: `${base}/2026-10-08/specification/overview/`,
    pinnedUrl: `${base}/${pinnedEdition}/specification/overview/`,
    sourceUrl: `ucp.dev @ ${pinnedEdition} (business profile)`,
    fields: {
      // Top-level wrapper.
      profile: ['ucp', 'keys', 'meta', 'supported_versions'],
      ucp: ['version', 'services', 'capabilities', 'keys'],
      service: ['version', 'spec', 'schema', 'transport', 'endpoint'],
      capability: ['version', 'spec', 'schema', 'extends'],
