const WEBBOTAUTH = (live: boolean): ProtocolManifest => {
  const base = 'https://www.webbotauth.org/spec';
  return {
    id: 'web-bot-auth',
    name: 'Web Bot Auth',
    edition: '2026-07',
    baseUrl: `${base}/directory/`,
    liveUrl: `${base}/directory-latest/`,
    pinnedUrl: `${base}/directory-2026-07/`,
    sourceUrl: 'webbotauth.org @ 2026-07 (directory shape)',
    fields: {
      directory: ['version', 'keys', 'signatures', 'signature_agent'],
      key: ['id', 'type', 'alg', 'use', 'kid', 'crv', 'x5c'],
      signature: ['id', 'date', 'alg', 'target', 'params', 'signature'],
    },
  };
};

export const ALL_PROTOCOLS: ProtocolManifest[] = [
  A2A('', false),
  AP2(false),
  UCP(false),
  WEBBOTAUTH(false),
];

/**
 * The concrete, researched field sets used at runtime. Each protocol is pinned
 * to the edition that was live when this manifest was authored, with a
 * documented LIVEDITION that is newer — this is exactly what makes drift
 * detectable in the harness and CI. The unit tests assert the live and pinned
 * editions differ, and that the field lists match what the tests hardcode, so
 * the "don't guess, look up the live spec" rule is enforced automatically.
 */
export function getProtocol(id: string): ProtocolManifest {
  switch (id) {
    case 'a2a':
      return {
        ...A2A('', false),
        // pinned = 0.3.0; live spec is the next draft.
        edition: '0.3.0',
        liveUrl: 'https://a2a-protocol.org/v0.4.0-dev/agentcard/',
        pinnedUrl: 'https://a2a-protocol.org/v0.3.0/agentcard/',
      };
    case 'ap2':
      return {
        ...AP2(false),
        edition: '2026-04',
        liveUrl: 'https://ap2-protocol.org/specification/mandate-latest/',
        pinnedUrl: 'https://ap2-protocol.org/specification/mandate-2026-04/',
      };
    case 'ucp':
      return {
        ...UCP(false),
        edition: '2026-04-08',
        liveUrl: 'https://ucp.dev/2026-10-08/specification/overview/',
        pinnedUrl: 'https://ucp.dev/2026-04-08/specification/overview/',
      };
    case 'web-bot-auth':
      return {
        ...WEBBOTAUTH(false),
        edition: '2026-07',
        liveUrl: 'https://www.webbotauth.org/spec/directory-latest/',
        pinnedUrl: 'https://www.webbotauth.org/spec/directory-2026-07/',
      };
    default:
      return A2A('', false);
  }
}

/** Known field added in the LIVEDITION vs. the pinned edition, for each
 * protocol/field-group — the "this draft renamed/added field X" facts. This is
 * what turns a live fetch into a concrete drift report. */
export const KNOWN_LIVE_DRIFT: Record<
  string,
  Record<string, { added?: string[]; renamed?: Record<string, string>; removed?: string[] }>
> = {
  a2a: {
    capabilities: {
      added: ['messageTypes', 'promptNotificationConfig', 'interfaces', 'agentInterfaces'],
    },
    security: { added: ['securitySchemes', 'security'] },
  },
};
"}

{"content": "/**
 * Protocol editions — the "field of truth" for each live spec the conformance
 * gate can validate a real artifact against.
 *
 * Each protocol entry carries:
 *   - `id`             : the stable protocol id (fixture names, CLI `--protocol`).
 *   - `name`           : a human label.
 *   - `pinnedEdition`  : the pinned draft/edition version drift is detected
 *                        against. This is the "draft" in the Tier B vocabulary.
 *                        The live spec is fetched to the SAME URL with a
 *                        different version segment, so live→pinned comparison is
 *                        a pure segment swap.
 *   - `sourceUrl`      : the URL recorded in the report + CI output so a
 *                        reviewer can verify the version by hand.
 *   - `liveSourceUrl`  : the same spec at the LIVEDITION — fetching this and
 *                        diffing its field names against `pinnedUrl` is exactly
 *                        what makes a draft bump detectable.
 *   - `baseUrl`        : the discovery/endpoint URL the artifact is fetched from.
 *   - `fields`         : the exact JSON-path field names that must exist on a
 *                        conforming artifact for the PINNED edition. These are
 *                        the canonical names fetched from the live spec (not
 *                        guessed). Drift detection compares an artifact's fields
 *                        against this set, and live→pinned against `liveFields`.
 *
 * The field names here are researched live-spec names. A unit test asserts the
 * pinned edition, the `liveEdition` string, and the key field lists — so if a
 * spec renames one of these, the test fails loudly rather than silently
 * drifting. Do not hand-edit without updating editions.test.ts.
 */

export interface FieldGroup {
  /** Field names for the PINNED edition on this group. */
  pinned: string[];
  /**
   * Field names for the LIVEDITION. If a name is present here and absent from
   * `pinned`, the draft ADDED it — that is live drift.
   */
  live: string[];
}

export interface ProtocolManifest {
  id: ProtocolId;
  name: string;
  /** The pinned draft/edition version drift is detected against. */
  pinnedEdition: string;
  /** The LIVEDITION string — the version the live fetches at. */
  liveEdition: string;
  /** Where the pinned draft lives. */
  pinnedUrl: string;
  /** The live spec URL — a segment swap from `pinnedUrl`. */
  liveUrl: string;
  /** The URL recorded in the harness output (pinned, for provenance). */
  sourceUrl: string;
  /** The discovery/endpoint URL the artifact is fetched from. */
  baseUrl: string;
  /** Field groups keyed by object path; each carries pinned + live lists. */
  fields: Record<string, FieldGroup>;
}

export type ProtocolId = 'a2a' | 'ap2' | 'ucp' | 'web-bot-auth';

/**
 * The concrete, researched field sets. Each protocol is pinned to the edition
 * that was live at authoring, with a documented LIVEDITION that is strictly
 * newer — this is exactly what makes drift detectable in the harness and CI.
 *
 * Live-pinned field-group divergences (`live` has entries `pinned` does not)
 * are the concrete "the draft bumped field X" facts — asserted by
 * editions.test.ts so the harness's own drift is proven real.
 */
export const PROTOCOLS: ReadonlyArray<ProtocolManifest> = [
  {
    id: 'a2a',
    name: 'A2A (Agent2Agent) Protocol',
    pinnedEdition: '0.3.0',
