          'agentExtensions',
          'messageTypes',
          'map',
          'pushNotificationConfig',
          'promptNotificationConfig',
        ],
      },
      security: {
        pinned: [],
        live: ['securitySchemes', 'security'],
      },
    },
  },
  {
    id: 'ap2',
    name: 'AP2 (Agent Payments Protocol)',
    pinnedEdition: '2026-04',
    liveEdition: '2026-10',
    pinnedUrl: 'https://ap2-protocol.org/specification/mandate-2026-04/',
    liveUrl: 'https://ap2-protocol.org/specification/mandate-2026-10/',
