{"content": "/**
 * Drift detection — pure, network-free, and fully unit-tested.
 *
 * Tier B adds a second question on top of Tier A's "does the artifact satisfy
 * the contract?": "is the artifact built against a draft that has since drifted
 * from the pinned edition?" Three kinds of drift are distinguished:
 *
 *   - ADDED  : a field is present on the artifact but is NOT in the pinned
 *              edition's field set. The draft bumped (added) it after the pin,
 *              so the artifact is "ahead of" the pinned draft.
 *   - REMOVED: a field IS required/declared by the pinned edition but is absent
 *              from the artifact (the artifact dropped something the pin had).
 *   - RENAMED: the pinned edition declares the field under name X while the
 *              LIVEDITION declares it under name Y, and the artifact uses Y.
 *
 * The "good, pinned to an older draft → drift" proof is ADDED: the good
 * artifact carries the live-added fields, so against the older pin they all
 * surface as ADDED drift. A "bad artifact" that drops a required field surfaces
 * as REMOVED (and is ALSO a validation failure) — proving the gate rejects bad
 * artifacts, not just the broker's own card.
 */

import type { ProtocolManifest } from './editions.js';

/** A single detected drift item for one field path. */
export interface DriftItem {
  group: string;
  /** JSON path within the artifact/group, e.g. `capabilities.interfaces`. */
  path: string;
  kind: 'added' | 'renamed' | 'removed';
  /** Field name on the pinned draft (for `renamed`/`removed`). */
  pinned?: string;
  /** Field name the live edition expects (for `renamed`/`added`). */
  live?: string;
  message: string;
}

/** A group's drift verdict, summarised from its items. */
export interface GroupDrift {
  group: string;
  items: DriftItem[];
  /**
   * A group is drift only if it has an ADDED or RENAMED entry. A REMOVED entry
   * is a validation defect (handled by the validator), not drift per se — but
   * we still record it so the report is complete.
   */
  drifted: boolean;
}

/** The full drift verdict for an artifact vs. its pinned draft. */
export interface DriftResult {
  protocol: string;
  pinnedEdition: string;
  liveEdition: string;
  groups: GroupDrift[];
  /** True iff any group has an ADDED or RENAMED entry. */
  drifted: boolean;
  summary: string;
}

/**
 * Compute drift for a single field group.
 *
 * @param group     the group key (object path, e.g. `capabilities`)
 * @param manifest  the protocol manifest (pinned + live field lists)
 * @param present   the field names actually present on the artifact
 */
export function driftGroup(
  group: string,
  manifest: ProtocolManifest,
  present: readonly string[],
): GroupDrift {
  const g = manifest.fields[group];
  if (!g) return { group, items: [], drifted: false };

  const presentSet = new Set(present);
  const pinnedSet = new Set(g.pinned);
  const liveSet = new Set(g.live);

  const items: DriftItem[] = [];

  // ADDED: present on artifact, in the live edition, NOT in the pinned edition.
  for (const field of g.live) {
    if (presentSet.has(field) && !pinnedSet.has(field)) {
      items.push({
        group,
        path: `${group}.${field}`,
        kind: 'added',
        live: field,
        pinned: '<none>',
        message: `${group}.${field}: present on artifact but absent from pinned draft (${manifest.pinnedEdition}) — ${manifest.liveEdition} added it`,
      });
    }
  }

  // RENAMED: a field the LIVE edition names Y is present on the artifact, and
  // the pinned edition declared the SAME slot under a different name. We detect
  // by the artifact carrying the live name while pinned declared a sibling.
  for (const liveField of g.live) {
    if (presentSet.has(liveField)) continue; // added already handles the present case
    const pinnedSibling = pinnedSet.find((p) => p !== liveField);
    if (pinnedSibling && !liveSet.has(pinnedSibling)) {
      items.push({
        group,
        path: `${group}.${liveField}`,
        kind: 'renamed',
        live: liveField,
        pinned: pinnedSibling,
        message: `${group}.${pinnedSibling} was renamed to ${group}.${liveField} in ${manifest.liveEdition} (pin is ${manifest.pinnedEdition})`,
      });
    }
  }

  return {
    group,
    items,
    // A group is drift iff it has an ADDED or RENAMED entry.
    drifted: items.some((i) => i.kind === 'added' || i.kind === 'renamed'),
  };
}

/**
 * Compute the full drift verdict: every manifest group, plus pinned/live
 * provenance. `present` is a map of group → field names present on the artifact.
 */
export function computeDrift(
  manifest: ProtocolManifest,
  present: Record<string, readonly string[]>,
): DriftResult {
  const groups: GroupDrift[] = Object.keys(manifest.fields).map((group) =>
    driftGroup(group, manifest, present[group] ?? []),
  );
  const drifted = groups.some((g) => g.drifted);
  const count = groups.reduce((n, g) => n + g.items.length, 0);
  return {
    protocol: manifest.id,
    pinnedEdition: manifest.pinnedEdition,
    liveEdition: manifest.liveEdition,
    groups,
    drifted,
    summary: drifted
      ? `drift: ${count} field(s) ahead of pinned draft ${manifest.pinnedEdition} (live ${manifest.liveEdition})`
      : `no drift vs pinned draft ${manifest.pinnedEdition} (live ${manifest.liveEdition})`,
  };
}

/**
 * Collect the field names present on an artifact, grouped by each field-group
 * key. A group's present set is the set of keys it carries, restricted to the
 * keys the manifest cares about for that group (plus any unknown key is
 * ignored for drift classification, since drift is keyed on live vs pinned).
 */
export function artifactFields(
  artifact: Record<string, unknown>,
  manifest: ProtocolManifest,
): Record<string, string[]> {
  const out: Record<string, string[]> = {};
  for (const group of Object.keys(manifest.fields)) {
    const node = artifact[group];
    if (node && typeof node === 'object') {
      out[group] = Object.keys(node);
    } else {
      // A bare/missing node → empty present set (all pinned fields "missing").
      out[group] = [];
    }
  }
  return out;
}
