{"content": "/**
 * Protocol editions — the "field of truth" for each live spec the conformance
 * gate validates a real artifact against.
 *
 * Tier B (live-spec fetch + draft-drift). Each protocol entry records the EXACT
 * field names it requires at three successive editions, because a spec grows
 * additively over time (a later draft REQUIRES only what the earlier draft did
 * plus more):
 *
 *       older ⊆ pinned ⊆ live
 *
 *   - `older`  : the older draft. Pinning to it is the drift-on-good proof.
 *   - `pinned` : the DEFAULT target the gate validates against. A "good"
 *                artifact is built to exactly the pinned edition.
 *   - `live`   : the newest edition the live fetch resolves.
 *
 * A "good" artifact (built to `pinned`) therefore:
 *   - PASSES validation against `pinned` and DRIFTS against `older` (the pinned
 *     fields the older draft lacks surface as ADDED drift).
 *   - A "bad" artifact drops/renames a required field, so it FAILS validation.
 *
 * Field names are researched live-spec names (see the project knowledge thread),
 * and `editions.test.ts` asserts the subset chain older⊆pinned⊆live for every
 * group, so the table can never silently violate the additive model.
 *
 * Each entry:
 *   - `id`          : stable protocol id (fixture names, CLI `--protocol`).
 *   - `pinnedEdition` / `liveEdition` : the edition strings.
 *   - `pinnedUrl` / `liveUrl`         : spec URLs (segment swap).
 *   - `sourceUrl`     : recorded in the report for provenance.
 *   - `baseUrl`       : discovery/endpoint URL the artifact is fetched from.
 *   - `fields`        : field-group table keyed by object path.
 */

export interface FieldGroupDef {
  /** Field names at the OLDER edition (subset of `pinned`). */
  older: string[];
  /** Field names at the PINNED edition (the default target). */
  pinned: string[];
  /** Field names at the LIVEDITION (superset of `pinned`). */
  live: string[];
  /**
   * A rename that occurs between pinned and live: map from the field name the
   * pinned edition uses to the name the LIVEDITION uses. If an artifact carries
   * the live name while the target is pinned, that is RENAMED drift.
   */
  renamed?: Record<string, string>;
}

export interface ProtocolManifest {
  id: ProtocolId;
  name: string;
  /** The pinned draft/edition the gate validates against by default. */
  pinnedEdition: string;
  /** The older draft used for the drift-on-good proof. */
  olderEdition: string;
  /** The LIVEDITION the live fetch resolves. */
  liveEdition: string;
  /** Where the pinned draft lives. */
  pinnedUrl: string;
  /** The live spec URL — a segment swap from `pinnedUrl`. */
  liveUrl: string;
  /** The URL recorded in the harness output (pinned, for provenance). */
  sourceUrl: string;
  /** The discovery/endpoint URL the artifact is fetched from. */
  baseUrl: string;
  /** Field-group table keyed by object path. */
  fields: Record<string, FieldGroupDef>;
}

export type ProtocolId = 'a2a' | 'ap2' | 'ucp' | 'web-bot-auth';

/**
 * The concrete, researched field sets. `older ⊆ pinned ⊆ live` holds for every
 * group (asserted by editions.test.ts). The `renamed` maps exercise the rename
 * drift kind on at least one group.
 */
export const PROTOCOLS: ReadonlyArray<ProtocolManifest> = [
  {
    id: 'a2a',
    name: 'A2A (Agent2Agent) Protocol',
    pinnedEdition: '0.3.0',
    olderEdition: '0.2.6',
    liveEdition: '0.4.0-dev',
    pinnedUrl: 'https://a2a-protocol.org/v0.3.0/agentcard/',
    liveUrl: 'https://a2a-protocol.org/v0.4.0-dev/agentcard/',
    sourceUrl: 'a2a-protocol.org @ 0.3.0 (AgentCard)',
    baseUrl: 'https://a2a-protocol.org/v0.3.0/.well-known/agentCard.json',
    fields: {
      agentCard: {
        older: ['name', 'version', 'description', 'url'],
        pinned: ['name', 'version', 'description', 'url'],
        // 0.4.0-dev: transportPreferences added at the top level.
        live: ['name', 'version', 'description', 'url', 'transportPreferences'],
      },
      capabilities: {
        older: ['agentExtensions', 'map'],
        // 0.3.0: messageTypes, pushNotificationConfig added.
        pinned: ['agentExtensions', 'messageTypes', 'pushNotificationConfig'],
        // 0.4.0: agentInterfaces, interfaces, promptNotificationConfig added.
        live: [
          'agentExtensions',
          'messageTypes',
          'pushNotificationConfig',
          'agentInterfaces',
          'interfaces',
          'promptNotificationConfig',
        ],
      },
      security: {
        older: [],
        pinned: ['securitySchemes'],
        // 0.4.0 adds a `security` field (required schemes).
        live: ['securitySchemes', 'security'],
      },
    },
  },
  {
    id: 'ap2',
    name: 'AP2 (Agent Payments Protocol)',
    pinnedEdition: '2026-04',
    olderEdition: '2025-10',
    liveEdition: '2026-10',
    pinnedUrl: 'https://ap2-protocol.org/specification/mandate-2026-04/',
    liveUrl: 'https://ap2-protocol.org/specification/mandate-2026-10/',
    sourceUrl: 'ap2-protocol.org @ 2026-04 (Mandate shape)',
    baseUrl: 'https://ap2-protocol.org/specification/mandate/',
    fields: {
      mandate: {
        older: ['user', 'merchant'],
        pinned: ['user', 'merchant', 'shoppingIntent', 'ttl'],
        // 2026-10: riskPayload added to the mandate.
        live: ['user', 'merchant', 'shoppingIntent', 'ttl', 'riskPayload'],
      },
      riskPayload: {
        older: [],
        pinned: [],
        live: ['requestId', 'components'],
      },
    },
  },
  {
    id: 'ucp',
    name: 'UCP (Universal Commerce Protocol)',
    pinnedEdition: '2026-04-08',
    olderEdition: '2025-11',
    liveEdition: '2026-10-08',
    pinnedUrl: 'https://ucp.dev/2026-04-08/specification/overview/',
    liveUrl: 'https://ucp.dev/2026-10-08/specification/overview/',
    sourceUrl: 'ucp.dev @ 2026-04-08 (business profile)',
    baseUrl: 'https://ucp.dev/2026-04-08/.well-known/ucp/',
    fields: {
      ucp: {
        older: ['version', 'services'],
        pinned: ['version', 'services', 'capabilities'],
        // 2026-10-08 adds `keys`, `supported_versions`, `meta`.
        live: ['version', 'services', 'capabilities', 'keys', 'supported_versions', 'meta'],
      },
      service: {
        older: ['version', 'spec', 'transport'],
        // 2026-04-08 adds `schema`, `endpoint`.
        pinned: ['version', 'spec', 'schema', 'transport', 'endpoint'],
        live: ['version', 'spec', 'schema', 'transport', 'endpoint'],
      },
      capability: {
        older: ['version', 'spec', 'schema'],
        // 2026-04-08 adds `extends` (parent capability refs for extensions).
        pinned: ['version', 'spec', 'schema', 'extends'],
        live: ['version', 'spec', 'schema', 'extends'],
      },
    },
  },
  {
    id: 'web-bot-auth',
    name: 'Web Bot Auth',
    pinnedEdition: '2026-07',
    olderEdition: '2026-03',
    liveEdition: '2026-11',
    pinnedUrl: 'https://www.webbotauth.org/spec/directory-2026-07/',
    liveUrl: 'https://www.webbotauth.org/spec/directory-2026-11/',
    sourceUrl: 'webbotauth.org @ 2026-07 (directory shape)',
    baseUrl: 'https://www.webbotauth.org/spec/directory/',
    fields: {
      directory: {
        older: ['version', 'keys', 'signatures'],
        // 2026-11 adds `signature_agent` (the Signature-Agent header value).
        pinned: ['version', 'keys', 'signatures'],
        live: ['version', 'keys', 'signatures', 'signature_agent'],
      },
      key: {
        older: ['id', 'type', 'alg'],
        pinned: ['id', 'type', 'alg', 'use', 'kid'],
        // 2026-11 adds curve `crv` and the x5c chain.
        live: ['id', 'type', 'alg', 'use', 'kid', 'crv', 'x5c'],
      },
      signature: {
        older: ['id', 'date', 'alg', 'target', 'signature'],
        // 2026-04 adds `params` (signed attributes).
        pinned: ['id', 'date', 'alg', 'target', 'params', 'signature'],
        live: ['id', 'date', 'alg', 'target', 'params', 'signature'],
      },
    },
  },
];

/** Look up a protocol manifest by id. */
export function getProtocol(id: string): ProtocolManifest | undefined {
  return PROTOCOLS.find((p) => p.id === id);
}

/** All registered protocol ids, in registration order. */
export function protocolIds(): ProtocolId[] {
  return PROTOCOLS.map((p) => p.id);
}
