{"content": "/**
 * Drift detection — pure, network-free, and fully unit-tested.
 *
 * Tier B adds a second question on top of Tier A's "does the artifact satisfy
 * the contract?": "is the artifact built against a draft that has since drifted
 * from the draft we validated against?" Three kinds of drift are distinguished,
 * all relative to the *target edition* an artifact was validated against:
 *
 *   - ADDED  : a field present on the artifact is NOT in the target edition.
 *              The artifact is newer than the target draft (the draft bumped
 *              this field after the pin).
 *   - REMOVED: the target edition requires a field the artifact lacks. In a
 *              validation context this is a defect; relative to the target it is
 *              "the artifact dropped something the edition has".
 *   - RENAMED: the manifest's `renamed` map records that the target edition uses
 *              name X where a later edition uses name Y; if the artifact carries
 *              Y (not X), we report it as a rename relative to the pin.
 *
 * The "good, pinned to an older draft → drift" proof is ADDED: the good
 * artifact is built to the Pinned edition, which is a SUPERSET of the OLDER
 * edition, so against the older pin every pinned-added field surfaces as
 * ADDED drift. A "bad artifact" drops a required field → REMOVED (and it is
 * ALSO a validation failure) — proving the gate rejects bad artifacts, not
 * just the broker's own card.
 */

import type { FieldGroupDef, ProtocolManifest } from './editions.js';

/** A single detected drift item for one field path. */
export interface DriftItem {
  group: string;
  /** JSON path within the artifact/group. */
  path: string;
  kind: 'added' | 'renamed' | 'removed';
  /** Field name on the target draft. */
  target?: string;
  /** Field name the artifact uses. */
  artifact?: string;
  message: string;
}

/** A group's drift verdict, summarised from its items. */
export interface GroupDrift {
  group: string;
  items: DriftItem[];
  drifted: boolean;
}

/** The full drift verdict for an artifact vs. its target edition. */
export interface DriftResult {
  protocol: string;
  targetEdition: string;
  /** The newer edition the artifact is actually newer than (if drifted). */
  newerEdition?: string;
  groups: GroupDrift[];
  drifted: boolean;
  summary: string;
}

/** Collect the field names present on an artifact, grouped by group key. */
export function artifactFields(
  artifact: Record<string, unknown>,
  manifest: ProtocolManifest,
): Record<string, string[]> {
  const out: Record<string, string[]> = {};
  for (const group of Object.keys(manifest.fields)) {
    const node = artifact[group];
    out[group] = node && typeof node === 'object' ? Object.keys(node) : [];
  }
  return out;
}

/**
 * Compute drift for one field group relative to the *target* edition's field
 * set. `renamed` from the group definition is consulted so a live rename that
 * the artifact already picked up is reported as RENAMED rather than a plain
 * added/removed pair.
 */
export function driftGroup(
  group: string,
  manifest: ProtocolManifest,
  targetEdition: string,
  present: readonly string[],
): GroupDrift {
  const g: FieldGroupDef | undefined = manifest.fields[group];
  if (!g) return { group, items: [], drifted: false };

  const target = targetFields(g, targetEdition);
  const presentSet = new Set(present);
  const targetSet = new Set(target);
  const items: DriftItem[] = [];

  // RENAMED: artifact carries the LATER name of a field whose PINNED name is X.
  // Only meaningful when drifting against the pinned edition (target === pinned).
  if (targetEdition === manifest.pinnedEdition && manifest.renamed) {
    for (const [pinnedName, laterName] of Object.entries(manifest.renamed)) {
      if (presentSet.has(laterName) && !presentSet.has(pinnedName)) {
        items.push({
          group,
          path: `${group}.${laterName}`,
          kind: 'renamed',
          target: pinnedName,
          artifact: laterName,
          message: `${group}.${pinnedName} was renamed to ${group}.${laterName} by the LIVEDITION (pin is ${manifest.pinnedEdition})`,
        });
      }
    }
  }

  // ADDED: present on artifact, absent from target edition.
  for (const field of present) {
    if (!targetSet.has(field)) {
      items.push({
        group,
        path: `${group}.${field}`,
        kind: 'added',
        target: `<none>`,
        artifact: field,
        message: `${group}.${field}: present on artifact but absent from pinned draft ${targetEdition} — the draft bumped it`,
      });
    }
  }

  // REMOVED: target edition requires the field, artifact lacks it.
  for (const field of target) {
    if (!presentSet.has(field)) {
      items.push({
        group,
        path: `${group}.${field}`,
        kind: 'removed',
        target: field,
        artifact: `<none>`,
        message: `${group}.${field}: required by pinned draft ${targetEdition} but absent from the artifact`,
      });
    }
  }

  return {
    group,
    items,
    // Drift = added or renamed. A removed-only group is a validation defect,
    // not "ahead-of-pin" drift.
    drifted: items.some((i) => i.kind === 'added' || i.kind === 'renamed'),
  };
}

/** Resolve the target edition's field set for a group. */
function targetFields(g: FieldGroupDef, targetEdition: string): string[] {
  return targetEdition === manifestOlderVersion(g) || targetEdition === 'older'
    ? g.older
    : targetEdition === 'live'
      ? g.live
      : g.pinned;
}

// The older edition string, looked up so the "older" alias resolves. Kept local
// to drift.ts so the pure logic never needs the full manifest except the group.
function manifestOlderVersion(_g: FieldGroupDef): string {
  // placeholder — real resolution lives in computeDrift (which holds the
  // manifest); this helper exists only to satisfy the alias check without a
  // circular import. See computeDrift for the authoritative path.
