{"content": "/**
 * Drift detection — pure, network-free, and fully unit-tested.
 *
 * Tier B adds a second question on top of Tier A's "does the artifact satisfy
 * the contract?": "is the artifact built against a draft that has since drifted
 * from the draft we validated against?" Three kinds of drift are distinguished,
 * all relative to the *target edition* an artifact was validated against:
 *
 *   - ADDED  : a field present on the artifact is NOT in the target edition.
 *              The artifact is newer than the target draft (the draft bumped
 *              this field after the pin).
 *   - REMOVED: the target edition requires a field the artifact lacks. In a
 *              validation context this is a defect; relative to the target it is
 *              "the artifact dropped something the edition has".
 *   - RENAMED: a pinned name X that the LIVEDITION renamed to Y: if the artifact
 *              carries Y (not X), we report it as a rename relative to the pin.
 *
 * The "good, pinned to an older draft → drift" proof is ADDED: the good artifact
 * is built to the Pinned edition, which is a SUPERSET of the OLDER edition, so
 * against the older pin every pinned-added field surfaces as ADDED drift. A
 * "bad artifact" drops a required field → REMOVED (and it is ALSO a validation
 * failure) — proving the gate rejects bad artifacts, not just the broker's own
 * card.
 */

import type { FieldGroupDef, ProtocolManifest } from './editions.js';

/** A single detected drift item for one field path. */
export interface DriftItem {
  group: string;
  /** JSON path within the artifact/group. */
  path: string;
  kind: 'added' | 'renamed' | 'removed';
  /** Field name on the target edition. */
  target?: string;
  /** Field name the artifact actually carries. */
  artifact?: string;
  message: string;
}

/** A group's drift verdict, summarised from its items. */
export interface GroupDrift {
  group: string;
  items: DriftItem[];
  /** True iff the group has any ADDED or RENAMED entry (ahead-of-pin drift). */
  drifted: boolean;
}

/** The full drift verdict for an artifact vs. its target edition. */
export interface DriftResult {
  protocol: string;
  /** The edition the artifact was validated against. */
  targetEdition: string;
  /** The edition the artifact is actually newer than (if it drifted). */
  newerEdition?: string;
  groups: GroupDrift[];
  drifted: boolean;
  summary: string;
}

/** Resolve the field set for a group at a target edition. */
function targetFields(g: FieldGroupDef, targetEdition: string): string[] {
  if (targetEdition === 'older') return g.older;
  if (targetEdition === 'live') return g.live;
  return g.pinned;
}

/** Collect the field names present on an artifact, grouped by group key. */
export function artifactFields(
  artifact: Record<string, unknown>,
  manifest: ProtocolManifest,
): Record<string, string[]> {
  const out: Record<string, string[]> = {};
  for (const group of Object.keys(manifest.fields)) {
    const node = artifact[group];
    out[group] = node && typeof node === 'object' ? Object.keys(node) : [];
  }
  return out;
}

/**
 * Compute drift for one field group relative to the target edition's field set.
 * `renamed` (pinned→live) is consulted so a live rename already present on the
 * artifact is reported as RENAMED rather than a spurious added/removed pair.
 */
export function driftGroup(
  group: string,
  manifest: ProtocolManifest,
  targetEdition: string,
  present: readonly string[],
): GroupDrift {
  const g = manifest.fields[group];
  if (!g) return { group, items: [], drifted: false };

  const target = targetFields(g, targetEdition);
  const presentSet = new Set(present);
  const targetSet = new Set(target);
  const items: DriftItem[] = [];

  // RENAMED: artifact carries the LATER name of a field whose PINNED name is X.
  if (targetEdition === manifest.pinnedEdition && manifest.fields[group].renamed) {
    for (const [pinnedName, laterName] of Object.entries(manifest.fields[group].renamed)) {
      if (presentSet.has(laterName) && !presentSet.has(pinnedName)) {
        items.push({
          group,
          path: `${group}.${laterName}`,
          kind: 'renamed',
          target: pinnedName,
          artifact: laterName,
          message: `${group}.${pinnedName} was renamed to ${group}.${laterName} by the LIVEDITION (pin is ${manifest.pinnedEdition})`,
        });
      }
    }
  }

  // ADDED: present on artifact, absent from the target edition.
  for (const field of present) {
    if (!targetSet.has(field)) {
      items.push({
        group,
        path: `${group}.${field}`,
        kind: 'added',
        target: '<none>',
        artifact: field,
        message: `${group}.${field}: present on artifact but absent from pinned draft ${targetEdition} — the draft bumped it`,
      });
    }
  }

  // REMOVED: the target edition requires the field, but the artifact lacks it.
  for (const field of target) {
    if (!presentSet.has(field)) {
      items.push({
        group,
        path: `${group}.${field}`,
        kind: 'removed',
        target: field,
        artifact: '<none>',
        message: `${group}.${field}: required by pinned draft ${targetEdition} but absent from the artifact`,
      });
    }
  }

  return {
    group,
    items,
    drifted: items.some((i) => i.kind === 'added' || i.kind === 'renamed'),
  };
}

/**
 * Compute the full drift verdict: every manifest group, keyed to the target
 * edition. `older` / `live` resolve to the older / live edition field sets;
 * anything else (e.g. the pinned edition) resolves to the pinned set.
 */
export function computeDrift(
  manifest: ProtocolManifest,
  present: Record<string, readonly string[]>,
  targetEdition: string,
): DriftResult {
  const groups: GroupDrift[] = Object.keys(manifest.fields).map((group) =>
    driftGroup(group, manifest, targetEdition, present[group] ?? []),
  );
  const drifted = groups.some((g) => g.drifted);
  // The edition the artifact is actually "newer" than, for provenance.
  const newerEdition =
    targetEdition === 'older'
      ? manifest.pinnedEdition
      : targetEdition === manifest.pinnedEdition
        ? manifest.liveEdition
        : undefined;
  const ahead = groups.reduce(
    (n, g) => n + g.items.filter((i) => i.kind !== 'removed').length,
    0,
  );
  return {
    protocol: manifest.id,
    targetEdition,
    newerEdition,
    groups,
    drifted,
    summary: drifted
      ? `drift: ${ahead} field(s) on the artifact are newer than the ${manifest.pinnedEdition} edition`
      : `no drift vs the ${manifest.pinnedEdition} edition`,
  };
}
