        pinned: ['user', 'merchant', 'shoppingIntent', 'ttl'],
        // 2026-10 adds riskPayload.
        live: ['user', 'merchant', 'shoppingIntent', 'ttl', 'riskPayload'],
      },
      riskPayload: {
