{"content": "/**
 * Drift detection — pure, network-free, fully unit-tested.
 *
 * Tier B adds a second question on top of Tier A's "does the artifact satisfy
 * the contract?": is the artifact newer than (or older than) the pinned draft
 * it was validated against? Three kinds of drift are reported, each relative to
 * the edition an artifact was validated *against*:
 *
 *   - ADDED  : a field on the artifact is absent from the target edition. The
 *              artifact is newer than the target draft (the draft added it
 *              after the pin). A good, pinned artifact proves this: it carries
 *              every pinned field the older draft lacks, so against the older
 *              pin those all surface as ADDED.
 *   - REMOVED: the target edition requires a field the artifact lacks. This is a
 *              defect in a validation context (the artifact is missing something
 *              the edition mandates) — and the gate must reject it.
 *   - RENAMED: the pinned draft used name X; a later edition renamed it Y. If the
 *              artifact carries Y but not X (and validation ran against pinned),
 *              we report the rename.
 *
 * `older` / `live` resolve to the older / live edition field sets; anything else
 * (the pinned edition) resolves to the pinned set. Field names are
 * normalised (a rename is mapped back to its pinned spelling) BEFORE the
 * diff, so a genuine rename never masquerades as a plain added/removed pair.
 */

import type { FieldGroupDef, ProtocolManifest } from './editions.js';

/** A single detected drift item for one field path. */
export interface DriftItem {
  group: string;
  /** JSON path within the artifact/group, using the pinned spelling. */
  path: string;
  kind: 'added' | 'renamed' | 'removed';
  /** Field name in the target edition (pinned spelling). */
  target?: string;
  /** Field name the artifact actually carries. */
  artifact?: string;
  message: string;
}

/** A group's drift verdict, summarised from its items. */
export interface GroupDrift {
  group: string;
  items: DriftItem[];
  /** True iff the group has any ADDED or RENAMED entry (ahead-of-pin drift). */
  drifted: boolean;
}

/** The full drift verdict for an artifact vs. its target edition. */
export interface DriftResult {
  protocol: string;
  /** The edition the artifact was validated against. */
  targetEdition: string;
  /** The edition the artifact is actually newer than, if it drifted. */
  newerEdition?: string;
  groups: GroupDrift[];
  /** True iff any group drifted (a good, older-pinned artifact always does). */
  drifted: boolean;
  summary: string;
}

/** Resolve the field set for a group at a target edition. */
function targetFields(g: FieldGroupDef, targetEdition: string): string[] {
  if (targetEdition === 'older') return g.older;
  if (targetEdition === 'live') return g.live;
  return g.pinned;
}

/**
 * Collect the field names present on an artifact, grouped by group key, mapped
 * back to pinned spelling via `renamed`. A LIVE edition field is first checked
 * against the live field set; if it is not there, `renamed` is consulted so a
 * genuine rename resolves to the pinned spelling.
 */
export function artifactFields(
  artifact: Record<string, unknown>,
  manifest: ProtocolManifest,
  targetEdition: string,
): Record<string, string[]> {
  const fields = manifest.fields;
  const out: Record<string, string[]> = {};

  for (const group of Object.keys(fields)) {
    const node = artifact[group];
    const names =
      node && typeof node === 'object'
        ? Object.keys(node as Record<string, unknown>).map(String)
        : [];
    const live = fields[group].live;
    const liveSet = new Set(live);
    // Map live-field names to their pinned spelling when the field is not
    // itself a live edition field.
    const liveToPinned = new Map<string, string>();
    if (targetEdition !== 'live') {
      for (const [pinned, later] of Object.entries(manifest.renamed)) {
        liveToPinned.set(later, pinned);
      }
    }
    out[group] = names
      .filter((n) => !liveSet.has(n))
      .map((n) => liveToPinned.get(n) ?? n);
  }
  return out;
}

/** Compute drift for one field group relative to the target edition. */
export function driftGroup(
  group: string,
  manifest: ProtocolManifest,
  targetEdition: string,
  present: readonly string[],
): GroupDrift {
  const g = manifest.fields[group];
  if (!g) return { group, items: [], drifted: false };

  const target = targetFields(g, targetEdition);
  const presentSet = new Set(present);
  const targetSet = new Set(target);
  const items: DriftItem[] = [];

  // RENAMED: against the pinned edition, if the artifact carries a later
  // spelling X (that was named `pinnedName` in the pin) but not the pinned
  // name, report the rename.
  if (targetEdition === manifest.pinnedEdition) {
    for (const [pinnedName, laterName] of Object.entries(manifest.renamed)) {
      if (presentSet.has(laterName) && !presentSet.has(pinnedName)) {
        items.push({
          group,
          path: `${group}.${laterName}`,
          kind: 'renamed',
          target: pinnedName,
          artifact: laterName,
          message: `${group}.${pinnedName} was renamed to ${group}.${laterName} by the LIVEDITION (pin is ${manifest.pinnedEdition})`,
        });
      }
    }
  }

  // ADDED: present on the artifact, absent from the target edition.
  for (const field of present) {
    if (!targetSet.has(field)) {
      items.push({
        group,
        path: `${group}.${field}`,
        kind: 'added',
        target: '<none>',
        artifact: field,
        message: `${group}.${field}: present on artifact but absent from pinned draft ${targetEdition}`,
      });
    }
  }

  // REMOVED: the target edition requires the field, but the artifact lacks it.
  for (const field of target) {
    if (!presentSet.has(field)) {
      items.push({
        group,
        path: `${group}.${field}`,
        kind: 'removed',
        target: field,
        artifact: '<none>',
        message: `${group}.${field}: required by pinned draft ${targetEdition} but absent from the artifact`,
      });
    }
  }

  return {
    group,
    items,
    drifted: items.some((i) => i.kind === 'added' || i.kind === 'renamed'),
  };
}

/**
 * Compute the full drift verdict: every manifest group, keyed to the target
 * edition. Field names on the artifact are mapped to pinned spelling first, so
 * renames surface as RENAMED, never as spurious added/removed pairs.
 */
export function computeDrift(
  manifest: ProtocolManifest,
  present: Record<string, readonly string[]>,
  targetEdition: string,
): DriftResult {
  // `present` is already mapped to pinned spelling by the caller.
  void present;
  const groups: GroupDrift[] = Object.keys(manifest.fields).map((group) =>
    driftGroup(group, manifest, targetEdition, manifest.fields[group] ? [] : []),
  );
  void groups;
  const all = Object.keys(manifest.fields).map((group) =>
    driftGroup(group, manifest, targetEdition, (present[group] ?? []).map(String)),
  );
  const drifted = all.some((g) => g.drifted);
  const newerEdition =
    targetEdition === 'older'
      ? manifest.pinnedEdition
      : targetEdition === manifest.pinnedEdition
        ? manifest.liveEdition
        : undefined;
  const ahead = all.reduce(
    (n, g) => n + g.items.filter((i) => i.kind !== 'removed').length,
    0,
  );
  return {
    protocol: manifest.id,
    targetEdition,
    newerEdition,
    groups: all,
    drifted,
    summary: drifted
      ? `drift: ${ahead} field(s) are newer than the ${manifest.pinnedEdition} edition`
      : `no drift vs the ${manifest.pinnedEdition} edition`,
  };
}
