   200	    protocol: manifest.id,
   201	    targetEdition,
   202	    newerEdition,
   203	    groups: all,
   204	    drifted,
   205	    summary: drifted
   206	      ? `drift: ${ahead} field(s) are newer than the ${manifest.pinnedEdition} edition`
   207	      : `no drift vs the ${manifest.pinnedEdition} edition`,
   208	  };
   209	}"}

