import type { ProtocolManifest } from './editions.js';

/** One group's diff against the pinned (required) and reference (pin) editions. */
export interface GroupDiff {
  group: string;
  /** Required fields, in pinned spelling. */
  required: string[];
  /** Present fields, mapped to pinned spelling. */
  present: string[];
  /** Pinned fields absent from the artifact (defects). */
  missing: string[];
  /** Present fields the reference (pin) edition lacks (drift). */
  drift: string[];
}

/** The full validation diff for an artifact against its manifest + pin. */
export interface ValidationDiff {
  protocol: string;
  /** The reference edition: `pinned` | `older` | `live`. */
  pin: string;
  groups: GroupDiff[];
  /** All missing (defect) fields across groups. */
  missing: string[];
  /** All drift (newer-than-reference) fields across groups. */
  drift: string[];
  /** Pass iff no missing field and no drift. */
  pass: boolean;
  summary: string;
}

/** Map a field name (possibly a live/later spelling) to pinned spelling. */
export function toPinned(
  name: string,
  manifest: ProtocolManifest,
): string {
  for (const [pinnedName, laterName] of Object.entries(manifest.renamed)) {
    if (name === laterName) return pinnedName;
  }
  return name;
}

/**
 * Present field names per group, mapped to pinned spelling via the rename map.
 * Returns `[]` for a group absent from the artifact.
 */
export function presentFields(
  artifact: Record<string, unknown>,
  manifest: ProtocolManifest,
): Record<string, string[]> {
  const out: Record<string, string[]> = {};
  for (const [group, g] of Object.entries(manifest.fields)) {
    const node = artifact[group];
    const names =
      node && typeof node === 'object'
        ? Object.keys(node as Record<string, unknown>).map(String)
        : [];
    out[group] = [...new Set(names.map((n) => toPinned(n, manifest)))];
    void g;
  }
  return out;
}

