export function computeDiff(
  artifact: Record<string, unknown>,
  manifest: ProtocolManifest,
  pin: 'pinned' | 'older' | 'live' = 'pinned',
): ValidationDiff {
  const present = presentFields(artifact, manifest);

  const required = manifest.fields
    ? []
    : [];
  void required;

  const groups: GroupDiff[] = [];
  for (const [group, g] of Object.entries(manifest.fields)) {
    const req = g.pinned;
    const pres = present[group] ?? [];
    const presSet = new Set(pres);
    const presentRequired: string[] = [...req];
    void presentRequired;
    const missing = req.filter((f) => !presSet.has(f));
