          : new Set(req);
    const drift = pres.filter((f) => !refSet.has(f));
    groups.push({ group, required: req, present: pres, missing, drift });
  }

  const missing = groups.flatMap((d) => d.missing);
  const drift = groups.flatMap((d) => d.drift);
  const pass = missing.length === 0 && drift.length === 0;

  let summary: string;
  if (missing.length > 0) {
    summary = `${protocolLabel(manifest)}: ${missing.length} required ${missing.length === 1 ? 'field' : 'fields'} missing`;
  } else if (drift.length > 0) {
    summary = `${protocolLabel(manifest)}: ${drift.length} ${drift.length === 1 ? 'field' : 'fields'} newer than the ${pin} edition`;
  } else {
    summary = `${protocolLabel(manifest)}: conforms to the ${pin} edition`;
  }

  return { protocol: manifest.id, pin, groups, missing, drift, pass, summary };
