{"path": "packages/conformance/src/run.ts", "start_line": 1, "end_line": 93, "total_lines": 93, "content": "     1	import { registry } from './registry.js';
     2	import {
     3	  type ContractCard,
     4	  type ConformanceResult,
     5	  type SpecProvenance,
     6	  type ValidatorContext,
     7	  type ValidationResult,
     8	} from './types.js';
     9	
    10	/** ANSI helpers for the terminal PASS/FAIL summary. */
    11	const CONFORMANCE_OK = '\x1B[32m'; // green
    12	const CONFORMANCE_WARN = '\x1B[31m'; // red
    13	const CONFORMANCE_NOTE = '\x1B[36m'; // cyan
    14	const RESET = '\x1B[0m';
    15	
    16	/**
    17	 * Run every registered validator over a card.
    18	 *
    19	 * Each validator's result is collected; `pass` is true only when every
    20	 * validator returned ok. Tier B validators may be async (the live-spec
    21	 * validators), so each result is awaited.
    22	 */
    23	export async function run(
    24	  card: ContractCard,
    25	  contractName: string,
    26	  context: ValidatorContext = {},
    27	): Promise<ConformanceResult> {
    28	  const results: ValidationResult[] = [];
    29	  for (const name of registry.names()) {
    30	    results.push(await registry.get(name)(card, context));
    31	  }
    32	  return {
    33	    contract: card,
    34	    contractName,
    35	    results,
    36	    pass: results.every((r) => r.ok),
    37	  };
    38	}
    39	
    40	/**
    41	 * Render a green/red PASS/FAIL summary to stdout. Each validator gets a line;
    42	 * a single failure is enough to flip the whole gate to red. Tier B also prints
    43	 * the live-spec provenance (pinned draft + live spec URLs) for validators that
    44	 * fetch, plus any drift detected against the pinned draft.
    45	 */
    46	export async function report(result: ConformanceResult): Promise<void> {
    47	  const bar = '\u2500'.repeat(64);
    48	  const line = (text: string) => console.log(text);
    49	
    50	  line('');
    51	  line(bar);
    52	  line(`  conformance · ${result.contractName}`);
    53	  line(bar);
    54	
    55	  for (const r of result.results) {
    56	    const tick = r.ok ? '✓' : '✗';
    57	    const colour = r.ok ? CONFORMANCE_OK : CONFORMANCE_WARN;
    58	    line(`  ${colour}${tick}${RESET}  ${r.name.padEnd(16)} ${r.message}`);
    59	    // Provenance block (one validator — a protocol — fetches).
    60	    if (r.spec) {
    61	      renderSpec(r.spec, line);
    62	    }
    63	    if (r.detail) {
    64	      line(`      ${CONFORMANCE_NOTE}· ${r.detail}${RESET}`);
    65	    }
    66	  }
    67	
    68	  line(bar);
    69	  const verdict = result.pass ? 'PASS' : 'FAIL';
    70	  const verdictColour = result.pass ? CONFORMANCE_OK : CONFORMANCE_WARN;
    71	  const failed = result.results.filter((r) => !r.ok).length;
    72	  line(
    73	    `  ${verdictColour}${verdict}${RESET}  — ${result.results.length} validators, ${failed} failed`,
    74	  );
    75	  line('');
    76	}
    77	
    78	/** Print the pinned/live provenance a single spec validator recorded. */
    79	function renderSpec(spec: SpecProvenance, line: (s: string) => void): void {
    80	  line(
    81	    `      ${CONFORMANCE_NOTE}[pinned draft ${spec.pinnedEdition ?? '?'}] ${spec.pinnedUrl ?? ''}${RESET}`,
    82	  );
    83	  if (spec.liveUrl) {
    84	    line(
    85	      `      ${CONFORMANCE_NOTE}[live spec ${spec.liveEdition ?? '?'}] ${spec.liveUrl}${RESET}`,
    86	    );
    87	  }
    88	  if (spec.drift) {
    89	    line(
    90	      `      ${CONFORMANCE_NOTE}[drift] ${spec.drift}${RESET}`,
    91	    );
    92	  }
    93	}"}

