    35	  missing: string[];
    36	  /** Present fields the reference (pin) edition lacks (drift). */
    37	  drift: string[];
    38	}
    39	
    40	/** The full validation diff for an artifact against its manifest + pin. */
    41	export interface ValidationDiff {
    42	  protocol: string;
    43	  /** The reference edition: `pinned` | `older` | `live`. */
    44	  pin: string;
    45	  groups: GroupDiff[];
    46	  /** All missing (defect) fields across groups. */
    47	  missing: string[];
    48	  /** All drift (newer-than-reference) fields across groups. */
    49	  drift: string[];
    50	  /** Pass iff no missing field and no drift. */
    51	  pass: boolean;
    52	  summary: string;
    53	}
