{"path": "packages/conformance/src/protocols/drift.ts", "start_line": 1, "end_line": 166, "total_lines": 166, "content": "     1	/**
     2	 * Drift detection — the pure, network-free engine.
     3	 *
     4	 * Tier B validates an artifact against the **pinned** edition (every pinned
     5	 * field is required), and reports version drift relative to a *reference*
     6	 * edition selected by the `pin` flag. `pinned` / `older` / `live` are the three
     7	 * editions in `older ⊆ pinned ⊆ live`:
     8	 *
     9	 *   - `missing` : a pinned field the artifact lacks. A defect — the gate fails.
    10	 *   - `drift`   : a field the artifact carries that the *reference* edition
    11	 *                 lacks — the artifact is newer than the reference. `pinned`
    12	 *                 and `older` fail on drift; `live` treats the newest edition
    13	 *                 as current (a live artifact drifts by zero).
    14	 *
    15	 * Field names are mapped to **pinned spelling** before diffing, via the
    16	 * manifest's `renamed` map, so a genuine rename (e.g. AP2 `agent`→`merchant`)
    17	 * never masquerades as a spurious missing/drift pair.
    18	 *
    19	 *   - pin=`pinned`  : strict vs pinned — no live extras, no defect.
    20	 *   - pin=`older`   : strict vs an older draft — a pinned artifact drifts on
    21	 *                     every pinned-only field. → FAIL (the drift proof).
    22	 *   - pin=`live`    : current — a live artifact drifts by zero. → PASS.
    23	 *
    24	 * Groups are located in the artifact by a `path` (a dot-separated walk; the
    25	 * group label is the default). A `presence` group only requires that its node
    26	 * exists — it has no sub-fields to diff. The node may be an object (its keys
    27	 * are the fields) or an array (the union of every element's keys — the shape
    28	 * the key/signature blocks take in the spec docs).
    29	 */
    30	
    31	import type { FieldGroupDef, ProtocolManifest } from './editions.js';
    32	
    33	/** One group's diff against the pinned (required) and reference (pin) editions. */
    34	export interface GroupDiff {
    35	  group: string;
    36	  /** The group's path in the artifact. */
    37	  path: string;
    38	  /** Required fields, in pinned spelling. */
    39	  required: string[];
    40	  /** Present fields, mapped to pinned spelling. */
    41	  present: string[];
    42	  /** Pinned fields absent from the artifact (defects). */
    43	  missing: string[];
    44	  /** Present fields the reference (pin) edition lacks (drift). */
    45	  drift: string[];
    46	}
    47	
    48	/** The full validation diff for an artifact against a manifest and pin. */
    49	export interface ValidationDiff {
    50	  protocol: string;
    51	  /** The reference edition: `pinned` | `older` | `live`. */
    52	  pin: string;
    53	  groups: GroupDiff[];
    54	  /** All missing (defect) fields across groups. */
    55	  missing: string[];
    56	  /** All drift (newer-than-reference) fields across groups. */
    57	  drift: string[];
    58	  /** Pass iff no missing field and no drift. */
    59	  pass: boolean;
    60	  summary: string;
    61	}
    62	
    63	/** Map a field name (possibly a live/later spelling) to pinned spelling. */
    64	export function toPinned(
    65	  name: string,
    66	  manifest: ProtocolManifest,
    67	): string {
    68	  for (const [pinnedName, laterName] of Object.entries(manifest.renamed)) {
    69	    if (name === laterName) return pinnedName;
    70	  }
    71	  return name;
    72	}
    73	
    74	/**
    75	 * Walk a dot-separated path in the artifact. Returns `undefined` when any
    76	 * segment is missing, so a group absent from the artifact simply fails its
    77	 * required fields rather than throwing.
    78	 */
    79	export function walkPath(
    80	  artifact: Record<string, unknown>,
    81	  path: string,
    82	): unknown {
    83	  const segs = path.split('.').filter((s) => s.length > 0);
    84	  let node: unknown = artifact;
    85	  for (const seg of segs) {
    86	    if (node == null || typeof node !== 'object') return undefined;
    87	    node = (node as Record<string, unknown>)[seg];
    88	  }
    89	  return node;
    90	}
    91	
    92	/** Field names present at a group's node, mapped to pinned spelling. */
    93	export function fieldsIn(node: unknown, manifest: ProtocolManifest): string[] {
    94	  if (node == null) return [];
    95	  if (Array.isArray(node)) {
    96	    const seen = new Set<string>();
    97	    for (const el of node) {
    98	      if (el && typeof el === 'object') {
    99	        for (const k of Object.keys(el as Record<string, unknown>)) {
   100	          seen.add(toPinned(k, manifest));
   101	        }
   102	      }
   103	    }
   104	    return [...seen];
   105	  }
   106	  return Object.keys(node as Record<string, unknown>).map((k) =>
   107	    toPinned(k, manifest),
   108	  );
   109	}
   110	
   111	/** The reference edition's field set (pinned spelling) for one group. */
   112	function referenceFields(
   113	  g: FieldGroupDef,
   114	  manifest: ProtocolManifest,
   115	  pin: string,
   116	): string[] {
   117	  if (pin === 'older') return (g.older ?? []).map((n) => toPinned(n, manifest));
   118	  if (pin === 'live') return (g.live ?? []).map((n) => toPinned(n, manifest));
   119	  return (g.pinned ?? []).map((n) => toPinned(n, manifest));
   120	}
   121	
   122	/** Compute the full diff for one artifact against a manifest and pin. */
   123	export function computeDiff(
   124	  artifact: Record<string, unknown>,
   125	  manifest: ProtocolManifest,
   126	  pin: 'pinned' | 'older' | 'live' = 'pinned',
   127	): ValidationDiff {
   128	  const groups: GroupDiff[] = Object.entries(manifest.fields).map(
   129	    ([group, g]) => {
   130	      const path = g.path ?? group;
   131	      const node = walkPath(artifact, path);
   132	      let present: string[];
   133	      let missing: string[];
   134	      let drift: string[];
   135	
   136	      if (g.presence) {
   137	        // Presence group: only the node's existence is required.
   138	        present = [];
   139	        missing = node == null ? [path] : [];
   140	        drift = [];
   141	      } else {
   142	        present = fieldsIn(node, manifest);
   143	        const presSet = new Set(pres);
   144	        missing = (g.pinned ?? []).filter((f) => !presSet.has(toPinned(f, manifest)));
   145	        const refSet = new Set(referenceFields(g, manifest, pin));
   146	        drift = present.filter((f) => !refSet.has(f));
   147	      }
   148	      return { group, path, required: g.pinned ?? [], present, missing, drift };
   149	    },
   150	  );
   151	
   152	  const missing = groups.flatMap((d) => d.missing);
   153	  const drift = groups.flatMap((d) => d.drift);
   154	  const pass = missing.length === 0 && drift.length === 0;
   155	
   156	  let summary: string;
   157	  if (missing.length > 0) {
   158	    summary = `${manifest.name} (${manifest.pinnedEdition}): ${missing.length} required ${missing.length === 1 ? 'field' : 'fields'} missing`;
   159	  } else if (drift.length > 0) {
   160	    summary = `${manifest.name} (${manifest.pinnedEdition}): ${drift.length} ${drift.length === 1 ? 'field' : 'fields'} newer than the ${pin} edition`;
   161	  } else {
   162	    summary = `${manifest.name} (${manifest.pinnedEdition}): conforms to the ${pin} edition`;
   163	  }
   164	
   165	  return { protocol: manifest.id, pin, groups, missing, drift, pass, summary };
   166	}"}

