import type { ProtocolManifest } from './editions.js';
import { computeDiff, type Pin } from './drift.js';  // Pin type defined in drift.ts
import type { SpecProvenance, ValidationResult } from '../types.js';

export function validateArtifact(
  artifact: Record<string, unknown>,
  manifest: ProtocolManifest,
  pin: Pin = 'pinned',
): ValidationResult {
  const diff = computeDiff(artifact, manifest, pin);
  const spec: SpecProvenance = {
    pinnedEdition: manifest.pinnedEdition,
    pinnedUrl: manifest.pinnedUrl,
    liveUrl: manifest.liveUrl,
    liveEdition: manifest.liveEdition,
  };
  const ok = diff.pass;
  if (ok) {
    // enrich provenance with the reference edition that was validated against
    if (pin !== 'pinned') spec.pin = pin;
    return { name: `conformance:${manifest.id}`, ok, message: diff.summary, spec };
  }
  let message: string;
  let detail: string;
  let driftLine: string | undefined;
  if (diff.missing.length > 0) {
    message = `${manifest.name}: ${diff.missing.length} required ${diff.missing.length === 1 ? 'field' : 'fields'} missing ${diff.missing.join(', ')}`;
    detail = `required (pinned ${manifest.pinnedEdition}) fields missing: ${diff.missing.join(', ')}`;
  } else {
    message = `${manifest.name}: ${diff.drift.length} ${diff.drift.length === 1 ? 'field' : 'fields'} newer than the ${pin} edition`;
    detail = `artifact is newer than the ${pin} edition (${manifest[pin+'Edition'... ]}): ${diff.drift.join(', ')}`;
    driftLine = `artifact is newer than ${pin}`;
  }
  spec.drift = driftLine;
  return { name: `conformance:${manifest.id}`, ok, message, detail, spec };
}
```

