import type { SpecProvenance } from '../types.js';

export interface FetchedSpec {
  url: string;
  ok: boolean;
  status?: number;
  body: string;
  size: number;
  /** The edition the resolved URL resolves to (path segment), if discernible. */
  edition?: string;
}

export interface SpecFetcher {
  fetch(url: string, opts?: { timeoutMs?: number }): Promise<FetchedSpec>;
}

export function makeSpecFetcher(): SpecFetcher {
  return {
    fetch: async (url, opts = {}) => {
      const timeoutMs = opts.timeoutMs ?? 8000;
      let controller: AbortController | undefined;
      let t: ReturnType<typeof setTimeout> | undefined;
      try {
        controller = new AbortController();
        t = setTimeout(() => controller?.abort(), timeoutMs);
        const res = await fetch(url, { signal: controller.signal, redirect: 'follow' });
        const body = await res.text();
        return { url, ok: res.ok, status: res.status, body, size: body.length };
      } catch (err) {
        return { url, ok: false, status: undefined, body: '', size: 0 };
      } finally {
        if (t) clearTimeout(t);
      }
    },
  };
}

/** The edition discernible from a resolved spec URL (last path segment). */
export function editionFromUrl(url: string): string {
  try {
    const u = new URL(url);
    const seg = u.pathname.split('/').filter(Boolean).pop() ?? '';
    return seg || undefined;
  } catch { return undefined; }
}

/** Enrich a ValidationResult's provenance with the live fetch result. */
export function withLiveProvenance(
  res: ValidationResult,
  manifest: ProtocolManifest,
  fetcher: SpecFetcher,
  opts?: { timeoutMs?: number },
): Promise<ValidationResult> {
  return fetcher.fetch(manifest.liveUrl, opts).then((spec) => {
    // attach to res.spec provenance
    const specProv = res.spec ?? (res.spec = {});
    if (spec.ok) specProv.liveReachable = true;
    else specProv.liveReachable = false;
    return res;
  });
}
```

