    10	/** ANSI helpers for the terminal PASS/FAIL summary. */
    11	const CONFORMANCE_OK = '\x1B[32m'; // green
    12	const CONFORMANCE_WARN = '\x1B[31m'; // red
    13	const CONFORMANCE_NOTE = '\x1B[36m'; // cyan
